// Generated from MarkdownPoint's Design principles deck, with the slide text outlined. Do not edit by hand.

interface MarkdownPointBannerDesign {
    /** The slide's id in the deck */
    id: string;
    /** True when the slide's scheme is dark, which picks the wordmark and the point color */
    dark: boolean;
    colors: {
        canvas: string;
        surface: string;
        text: string;
        muted: string;
        accent: string;
    };
    /** The slide's two text boxes as presentation.md has them, with ==highlights== and <br> */
    eyebrow: string;
    statement: string;
    /** The slide as a standalone SVG document, its text outlined */
    svg: string;
}

